import csv, json, re
from datetime import datetime
from io import StringIO

BATCHES = ["/app/batches/customers_2025_01.csv", "/app/batches/customers_2025_02.csv"]

COL_MAP = {
    "id": "customer_id",
    "full_name": "name",
    "joined": "signup_date",
    "spend_usd": "total_spend",
}

def normalize_col(c):
    return COL_MAP.get(c.strip(), c.strip())

def parse_date(s):
    for fmt in ("%Y-%m-%d", "%m/%d/%Y"):
        try:
            return datetime.strptime(s, fmt).strftime("%Y-%m-%d")
        except ValueError:
            pass
    return None

reject_reasons = {}
def reject(reason):
    reject_reasons[reason] = reject_reasons.get(reason, 0) + 1

input_rows = 0
rejected = 0
valid = {}  # customer_id -> (row_dict, updated_at)
duplicates_replaced = 0

for path in BATCHES:
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        reader.fieldnames = [normalize_col(c) for c in reader.fieldnames]
        for row in reader:
            input_rows += 1
            row = {k: v.strip() for k, v in row.items()}

            cid = row.get("customer_id", "")
            if not cid:
                reject("missing customer_id"); rejected += 1; continue

            email = row.get("email", "").lower()
            if "@" not in email:
                reject("invalid email"); rejected += 1; continue

            date = parse_date(row.get("signup_date", ""))
            if date is None:
                reject("invalid signup_date"); rejected += 1; continue

            spend_raw = row.get("total_spend", "")
            try:
                spend = f"{float(spend_raw):.2f}"
            except ValueError:
                reject("non-numeric spend"); rejected += 1; continue

            updated_at = row.get("updated_at", "")
            out = {"customer_id": cid, "name": row.get("name", ""), "email": email,
                   "signup_date": date, "total_spend": spend}

            if cid in valid:
                if updated_at > valid[cid][1]:
                    duplicates_replaced += 1
                    valid[cid] = (out, updated_at)
                else:
                    duplicates_replaced += 1
            else:
                valid[cid] = (out, updated_at)

rows = sorted(valid.values(), key=lambda x: x[0]["customer_id"])

import os
os.makedirs("/app/normalized", exist_ok=True)

with open("/app/normalized/customers.csv", "w", newline="", encoding="utf-8") as f:
    writer = csv.DictWriter(f, fieldnames=["customer_id","name","email","signup_date","total_spend"])
    writer.writeheader()
    for row, _ in rows:
        writer.writerow(row)

report = {
    "input_rows": input_rows,
    "valid_rows": len(valid),
    "rejected_rows": rejected,
    "duplicates_replaced": duplicates_replaced,
    "reject_reasons": reject_reasons,
}
with open("/app/quality_report.json", "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2)
    f.write("\n")

print("Done.")

